import{_ as a}from"./chunks/rmlui.IQCB0h4b.js";import{_ as r,o as e,c as d,a2 as i}from"./chunks/framework.Ky-Ipuyb.js";const f=JSON.parse('{"title":"RmlUi 指南","description":"","frontmatter":{"lang":"zh-CN","sourcePath":"docs/rmlui/README.zh-CN.md"},"headers":[],"relativePath":"zh/rmlui/index.md","filePath":"zh/rmlui/index.md"}'),h={name:"zh/rmlui/index.md"};function l(s,t,o,n,m,u){return e(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="rmlui-指南" tabindex="-1">RmlUi 指南 <a class="header-anchor" href="#rmlui-指南" aria-label="Permalink to &quot;RmlUi 指南&quot;">​</a></h1><p><a class="library-brand" href="https://mikke89.github.io/RmlUiDoc/"><img src="'+a+`" width="246" height="84" alt="RmlUi"></a></p><p>使用 <code>sfml.js-rmlui</code> 在 SFML 窗口内构建文档式界面：RML 描述元素树，RCSS 控制外观，JavaScript 管理应用状态和事件处理。当前源码面向 RmlUi 6.3 和 SFML 3.1。</p><p>阅读前需了解 JavaScript 和 <a href="/zh/guide/window">SFML 窗口</a>。RmlUi 6.3 的语法类似 HTML/CSS，但没有嵌入浏览器。<a href="/zh/rmlui/data-models">原生数据模型</a>涵盖标量和回调绑定、递归记录及数组、自定义变量、共享数值存储和稀疏更新。下列指南介绍运行时、文档树、样式、渲染、输入、字体、脚本和资源所有权；<a href="/zh/reference/rmlui/" target="_self">API 参考</a>说明对应的 TypeScript 接口约定。</p><h2 id="什么是-rmlui" tabindex="-1">什么是 RmlUi <a class="header-anchor" href="#什么是-rmlui" aria-label="Permalink to &quot;什么是 RmlUi&quot;">​</a></h2><p><a href="https://github.com/mikke89/RmlUi" target="_blank" rel="noreferrer">RmlUi</a> 是一个采用类 HTML/CSS 文档语法的 C++ 界面库。它使用保留模式（Retained Mode）：加载 RML 后创建持久的元素树，用 RCSS 设置样式，再根据应用状态修改具体元素。RmlUi 负责布局和生成几何数据，本包通过 SFML 完成绘制。</p><p>它适合游戏菜单、HUD、背包窗口，以及希望把布局和视觉设计放在独立资源文件中的界面。RML、RCSS 和 Node.js 事件处理代码共同工作，运行时没有浏览器 DOM 或网页 JavaScript 环境。需要逐帧调用控件来组合工具界面时，可阅读 <a href="/zh/imgui/">ImGui 指南</a>。</p><p><a href="https://mikke89.github.io/RmlUiDoc/" target="_blank" rel="noreferrer">官方文档</a> · <a href="https://github.com/mikke89/RmlUi" target="_blank" rel="noreferrer">官方仓库</a></p><h2 id="文档目录" tabindex="-1">文档目录 <a class="header-anchor" href="#文档目录" aria-label="Permalink to &quot;文档目录&quot;">​</a></h2><h3 id="入门与文档" tabindex="-1">入门与文档 <a class="header-anchor" href="#入门与文档" aria-label="Permalink to &quot;入门与文档&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章节</th><th>内容</th></tr></thead><tbody><tr><td><a href="/zh/rmlui/getting-started">快速开始</a></td><td>运行计数器，了解初始化、字体和帧顺序</td></tr><tr><td><a href="/zh/rmlui/rml-rcss">RML 与 RCSS 入门</a></td><td>编写标签、选择器和布局，连接点击事件，查阅官方语法</td></tr><tr><td><a href="/zh/rmlui/documents">文档与事件</a></td><td>加载 RML、修改元素、注册监听器与释放原生对象</td></tr><tr><td><a href="/zh/rmlui/streams">字节流</a></td><td>文件、内存与回调流的读取和生命周期</td></tr><tr><td><a href="/zh/rmlui/strings">字符串与资源 URL</a></td><td>字符串处理、资源路径与 URL</td></tr></tbody></table><h3 id="元素、布局与控件" tabindex="-1">元素、布局与控件 <a class="header-anchor" href="#元素、布局与控件" aria-label="Permalink to &quot;元素、布局与控件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章节</th><th>内容</th></tr></thead><tbody><tr><td><a href="/zh/rmlui/element-state">元素类名、属性与焦点</a></td><td>修改元素状态，管理焦点与类名</td></tr><tr><td><a href="/zh/rmlui/element-utilities">元素工具</a></td><td>定位、文本测量、投影边界与裁剪几何</td></tr><tr><td><a href="/zh/rmlui/layout">元素布局、滚动与投影</a></td><td>布局尺寸、滚动位置与坐标投影</td></tr><tr><td><a href="/zh/rmlui/boxes">盒值与渲染盒</a></td><td>盒模型数据和渲染盒</td></tr><tr><td><a href="/zh/rmlui/controls">表单控件</a></td><td>输入框、选择控件与表单操作</td></tr><tr><td><a href="/zh/rmlui/text-panels">文本、进度条与标签页</a></td><td>文本元素、进度显示与标签页</td></tr><tr><td><a href="/zh/rmlui/vector-elements">SVG 与 Lottie</a></td><td>原生矢量元素、装饰器、动画帧和源文件</td></tr><tr><td><a href="/zh/rmlui/rtti-default-actions">原生类型与默认动作</a></td><td>元素类型识别和默认事件动作</td></tr></tbody></table><h3 id="样式、动画与渲染" tabindex="-1">样式、动画与渲染 <a class="header-anchor" href="#样式、动画与渲染" aria-label="Permalink to &quot;样式、动画与渲染&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章节</th><th>内容</th></tr></thead><tbody><tr><td><a href="/zh/rmlui/numeric-values">数值与单位</a></td><td>类型化数值、单位与转换</td></tr><tr><td><a href="/zh/rmlui/properties">类型化属性</a></td><td>属性定义、解析与类型化值</td></tr><tr><td><a href="/zh/rmlui/animation">动画与缓动</a></td><td>元素动画、关键帧与缓动</td></tr><tr><td><a href="/zh/rmlui/geometry-utilities">原生几何与卷积</a></td><td>批量生成网格，在共享 alpha 缓冲区上运行滤镜</td></tr><tr><td><a href="/zh/rmlui/resources">渲染资源</a></td><td>纹理、着色器、滤镜与工厂资源</td></tr><tr><td><a href="/zh/rmlui/render-state">渲染状态</a></td><td>裁剪、图层、回调纹理与状态恢复</td></tr><tr><td><a href="/zh/rmlui/rendering">渲染与 Retina</a></td><td>组合 SFML 与 RmlUi、适配高密度显示及了解效果支持</td></tr></tbody></table><h3 id="运行时与扩展" tabindex="-1">运行时与扩展 <a class="header-anchor" href="#运行时与扩展" aria-label="Permalink to &quot;运行时与扩展&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章节</th><th>内容</th></tr></thead><tbody><tr><td><a href="/zh/rmlui/plugins">插件</a></td><td>插件注册和运行时回调</td></tr><tr><td><a href="/zh/rmlui/scripts">文档脚本</a></td><td>Node.js 与 Lua 文档脚本</td></tr><tr><td><a href="/zh/rmlui/data-models">原生数据模型</a></td><td>绑定、表达式、共享数组与稀疏更新</td></tr><tr><td><a href="/zh/rmlui/fonts">字体</a></td><td>字体引擎、整形与字形图集</td></tr><tr><td><a href="/zh/rmlui/debugger">原生 Debugger</a></td><td>在独立宿主中检查元素、日志与数据模型反射</td></tr><tr><td><a href="/zh/rmlui/performance">共享存储与批处理</a></td><td>提交数值命令、批量自定义计算及预加载资源</td></tr><tr><td><a href="/zh/rmlui/source-layout">源码目录</a></td><td>Native 绑定、TypeScript 接口与工具的归属</td></tr><tr><td><a href="/zh/rmlui/api">API 指南</a></td><td>查找类型、默认值、返回值和生命周期契约</td></tr></tbody></table><p>指南和从源码生成的 API 参考均维护英文、简体中文、日文、韩文版本。</p><h2 id="运行示例" tabindex="-1">运行示例 <a class="header-anchor" href="#运行示例" aria-label="Permalink to &quot;运行示例&quot;">​</a></h2><p>在 monorepo 根目录执行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/bootstrap.cjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/sfml.js-rmlui/examples/demo.cjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/sfml.js-rmlui/examples/official.cjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> variables</span></span></code></pre></div><p><a href="/zh/examples/rmlui">示例目录</a>提供截图、操作说明和源码链接。计数器的 Increment 按钮可以点击计数；variables 页的任务按钮仅展示悬停样式。</p><h2 id="所有权边界" tabindex="-1">所有权边界 <a class="header-anchor" href="#所有权边界" aria-label="Permalink to &quot;所有权边界&quot;">​</a></h2><p>进程级运行时绑定一个 <code>RenderWindow</code>，归初始化它的 Node.js 环境和线程所有，管理上下文、文档、字体和渲染资源。元素包装器共享原生有效性。JS 引用会保活持有所有权的脱离树；已挂载节点的生命周期由原生父节点决定。销毁时自动释放监听器，访问失效包装器会抛出异常。关闭 SFML 窗口前关闭 RmlUi。文档延迟销毁和 Worker 限制见<a href="/zh/rmlui/documents#原生对象生命周期">原生对象生命周期</a>。</p>`,24)])])}const b=r(h,[["render",l]]);export{f as __pageData,b as default};
